package com.nigson.commerce.fulfillment;
import java.util.*;
import java.time.Clock;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.party.AddressRules;
import com.nigson.commerce.pricing.PricingValues;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Owned bounded rule persistence and caller-transaction fee selection. */
public final class JdbcDeliveryRules implements DeliveryRuleRepository,DeliveryRules {
 private final JdbcTemplate jdbc;private final Clock clock;
 public JdbcDeliveryRules(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 private static final String SELECT="SELECT id,market_id,country_code,region_code,postal_prefix,fee,free_above,priority,active,version FROM commerce.delivery_rule";
 private static FulfillmentValues.Rule row(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new FulfillmentValues.Rule(r.getObject("id",UUID.class),r.getObject("market_id",UUID.class),r.getString("country_code"),r.getString("region_code"),r.getString("postal_prefix"),amount(r.getBigDecimal("fee")),r.getBigDecimal("free_above")==null?null:amount(r.getBigDecimal("free_above")),r.getInt("priority"),r.getBoolean("active"),r.getLong("version"));}
 private static String amount(BigDecimal amount){try{return PricingValues.minor(PricingValues.decimal(amount),2).toPlainString();}catch(Problem.Failure bad){throw FulfillmentValues.rule();}}
 private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private void lockMarkets(Collection<UUID> markets){transaction();for(UUID id:markets.stream().distinct().sorted(Comparator.comparing(UUID::toString)).toList())jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"delivery-rules:"+id);}
 private void coverage(UUID market,String country,String region,boolean active){var rows=jdbc.queryForList("SELECT m.enabled,d.delivery_enabled,d.address_rules::text FROM commerce.market m JOIN commerce.currency c ON c.code=m.currency_code JOIN commerce.market_destination d ON d.market_id=m.id WHERE m.id=? AND m.code='NG' AND c.code='NGN' AND c.active AND c.minor_unit=2 AND d.country_code=? FOR SHARE OF m,c,d",market,country);if(rows.size()!=1)throw FulfillmentValues.rule();var row=rows.getFirst();if(active){if(!Boolean.TRUE.equals(row.get("enabled"))||!Boolean.TRUE.equals(row.get("delivery_enabled")))throw FulfillmentValues.rule();AddressRules address;try{address=AddressRules.parse(EventCodec.JSON.readTree(row.get("address_rules").toString()));}catch(Problem.Failure invalid){throw FulfillmentValues.rule();}if(region!=null&&!address.regionCodes().isEmpty()&&!address.regionCodes().contains(region))throw FulfillmentValues.rule();}}
 private List<FulfillmentValues.Rule> rules(UUID market,boolean lock){var rules=jdbc.query(SELECT+" WHERE market_id=? ORDER BY id LIMIT 501"+(lock?" FOR SHARE":""),JdbcDeliveryRules::row,market);if(rules.size()>500)throw FulfillmentValues.rule();return rules;}
 public FulfillmentValues.Rule find(UUID id,boolean lock){var rows=jdbc.query(SELECT+" WHERE id=?"+(lock?" FOR UPDATE":""),JdbcDeliveryRules::row,id);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);return rows.getFirst();}
 private FulfillmentValues.Rule proposed(UUID id,FulfillmentValues.RuleInput i,long version){return new FulfillmentValues.Rule(id,i.marketId(),i.countryCode(),i.regionCode(),i.postalPrefix(),amount(new BigDecimal(i.fee())),i.freeAbove()==null?null:amount(new BigDecimal(i.freeAbove())),i.priority(),i.active(),version);}
 private void valid(FulfillmentValues.Rule proposed,UUID excluded){coverage(proposed.marketId(),proposed.countryCode(),proposed.regionCode(),proposed.active());var all=rules(proposed.marketId(),false);if(excluded==null&&all.size()>=500)throw FulfillmentValues.rule();for(var rule:all)if(!rule.id().equals(excluded)&&DeliverySpecificity.ambiguous(rule,proposed))throw FulfillmentValues.rule();}
 public FulfillmentValues.Rule create(FulfillmentValues.RuleInput input,String actor){lockMarkets(List.of(input.marketId()));UUID id=EventCodec.uuid7(clock.instant());var value=proposed(id,input,0);valid(value,null);jdbc.update("INSERT INTO commerce.delivery_rule(id,created_by,updated_by,market_id,country_code,region_code,postal_prefix,fee,free_above,priority,active) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,actor,actor,value.marketId(),value.countryCode(),value.regionCode(),value.postalPrefix(),new BigDecimal(value.fee()),value.freeAbove()==null?null:new BigDecimal(value.freeAbove()),value.priority(),value.active());return find(id,false);}
 public FulfillmentValues.Rule update(UUID id,long expected,FulfillmentValues.RuleInput input,String actor){var before=find(id,false);lockMarkets(List.of(before.marketId(),input.marketId()));before=find(id,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();var value=proposed(id,input,expected+1);valid(value,id);jdbc.update("UPDATE commerce.delivery_rule SET market_id=?,country_code=?,region_code=?,postal_prefix=?,fee=?,free_above=?,priority=?,active=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",value.marketId(),value.countryCode(),value.regionCode(),value.postalPrefix(),new BigDecimal(value.fee()),value.freeAbove()==null?null:new BigDecimal(value.freeAbove()),value.priority(),value.active(),java.sql.Timestamp.from(clock.instant()),actor,id);return find(id,false);}
 public Fee resolve(UUID market,String country,String region,String postal,BigDecimal subtotal){transaction();if(subtotal==null||subtotal.signum()<0)throw ApiValues.invalid();coverage(market,country,region,true);var rule=DeliverySpecificity.select(rules(market,true),country,region,postal);BigDecimal fee=rule.freeAbove()!=null&&subtotal.compareTo(new BigDecimal(rule.freeAbove()))>=0?BigDecimal.ZERO.setScale(2):new BigDecimal(rule.fee());return new Fee(rule.id(),rule.version(),fee.toPlainString());}
}
